(function(){'use strict';const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',event=>{const id=link.getAttribute('href');if(!id||id==='#')return;const target=document.querySelector(id);if(target){event.preventDefault();target.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});history.pushState(null,'',id)}}));const nodes=document.querySelectorAll('.reveal');if(reduced||!('IntersectionObserver'in window)){nodes.forEach(node=>node.classList.add('is-visible'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});nodes.forEach(node=>observer.observe(node))})();